                                    <div role="main" id="mc-main-content">
                                        <h1 class="script">Read from Data File</h1>
                                        <p class="ref-purpose-script"><span class="mc-variable ui-strings-scriptsteps.vUserFileRead variable">Reads data from an open data file.</span>
                                        </p>
                                        <div class="ref-see-also-block">
                                            <h2 class="ref-see-also-head" data-mc-autonum="See also"><span class="autonumber"><span>See also</span></span>&#160;</h2>
                                            <ul class="ref-see-also-list">
                                                <li><a href="importing-data.html" class="MCXref xref">Importing data into FileMaker Pro</a>
                                                </li>
                                                <li><a href="scripts.html" class="MCXref xref">Automating tasks with scripts</a>
                                                </li>
                                            </ul>
                                        </div>
                                        <h2 class="ref-options-head" data-mc-autonum="Options"><span class="autonumber"><span>Options</span></span>&#160;</h2>
                                        <ul>
                                            <li><strong>File ID</strong> is a numeric expression that specifies the file ID of an open data file. See <a class="LinktoScriptStep MCXref xref xrefLinktoScriptStep" href="open-data-file.html">Open Data File script step</a>.</li>
                                            <li><strong>Amount</strong> specifies the number of bytes to read if <strong>Read as</strong> is <strong>UTF-8 </strong>or <strong>Bytes</strong>. For <strong>UTF-16</strong>, <strong>Amount</strong> is the number of Unicode code units to read. If <strong>Amount</strong> is not specified (set to nothing), the entire file is read.</li>
                                            <li><strong>Target</strong> is the field or variable to store the data read from the file.</li>
                                            <li><strong>Read as</strong> specifies the character encoding of the file.<ul><li><strong>UTF-16</strong> is FileMaker''s default 16-bit Unicode (UTF-16 little endian) character encoding.</li><li><strong>UTF-8</strong> is 8-bit Unicode character encoding.</li><li><strong>Bytes</strong> assumes no specific character encoding, but instead reads one byte at a time. If the target is a variable or container field, data read from the file is stored as container data with the same filename as the specified file.</li></ul></li>
                                        </ul>
                                        <div class="compat-wrapper">
                                            <h2 class="ref-compat-head" data-mc-autonum="Compatibility"><span class="autonumber"><span>Compatibility</span></span>&#160;</h2>
                                            <table cellspacing="0" class="TableStyle-CompTable" style="mc-table-style: url(''resources/tablestyles/comptable.css'');">
                                                <thead>
                                                    <tr class="TableStyle-CompTable-Head-Header1">
                                                        <td class="TableStyle-CompTable-HeadE-Column1-Header1"><span class="mc-variable compatibility-table-values.Heading:Product variable">Product</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-HeadD-Column2-Header1"><span class="mc-variable compatibility-table-values.Heading:Supported variable">Supported</span>
                                                        </td>
                                                    </tr>
                                                </thead>
                                                <tbody>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:Pro variable">FileMaker Pro</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:Go variable">FileMaker Go</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:WebD variable">FileMaker WebDirect</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:No variable">No</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:Server variable">FileMaker Server</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:Cloud variable">FileMaker Cloud</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:DAPI variable">FileMaker Data API</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:No variable">No</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyB-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:CWP variable">Custom Web Publishing</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyA-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                </tbody>
                                            </table>
                                        </div>
                                        <h2 class="ref-orig-head" data-mc-autonum="Originated in version"><span class="autonumber"><span>Originated in version</span></span>&#160;</h2>
                                        <p class="or-origin">18.0</p>
                                        <h2 class="ref-desc-head" data-mc-autonum="Description"><span class="autonumber"><span>Description</span></span>&#160;</h2>
                                        <p>This script step reads data specified by <strong>Amount</strong> starting at the current read-write position, or it reads the entire file if <strong>Amount</strong> is not specified. See <a href="set-data-file-position.html" class="MCXref xref">Set Data File Position</a>.</p>
                                        <p>The maximum amount of data this script step can read at a time is 64 MB. If a file is larger than 64 MB, you can perform this script step multiple times, reading an amount no larger than 64 MB each time.</p>
                                        <h2 class="notes-head" data-mc-autonum="Notes"><span class="autonumber"><span>Notes</span></span>&#160;</h2>
                                        <ul>
                                            <li>Performance is best when reading no more than 64 KB.</li>
                                            <li>When reading Unicode text from a portion of a file, only part of a character may be read if the character consists of multiple code units. If you expect to read text from a UTF-8 or UTF-16 file, it may be safer to read the entire file at one time unless you are sure of the number of code points per character.</li>
                                        </ul>
                                        <h2 class="ref-example1-head" data-mc-autonum="Example 1"><span class="autonumber"><span>Example 1</span></span>&#160;</h2>
                                        <p>Reads the contents of an open file with a file ID of 2 and stores the data in a variable.</p>
                                        <div class="codeSnippet"><a class="codeSnippetCopyButton" role="button" href="javascript:void(0);">Copy</a>
                                            <div class="codeSnippetBody" data-mc-use-line-numbers="False" data-mc-line-number-start="1" data-mc-continue="False"><pre><code>Read from Data File [ File ID: 2 ; Amount (bytes): ; Target: $variable ; Read as: Bytes ]</code></pre>
                                            </div>
                                        </div>
                                        <h2 class="ref-examplen-head" data-mc-autonum="Example 2"><span class="autonumber"><span>Example 2</span></span>&#160;</h2>
                                        <p>Checks whether a file named change.log exists in the Documents folder. If it does, reads the first 100 UTF-8 code units into the Utilities::Log Entry text field.</p>
                                        <div class="codeSnippet"><a class="codeSnippetCopyButton" role="button" href="javascript:void(0);">Copy</a>
                                            <div class="codeSnippetBody" data-mc-use-line-numbers="False" data-mc-line-number-start="1" data-mc-continue="False"><pre><code>Set Variable [ $file ; Value: Get ( DocumentsPath ) &amp; "change.log" ]<br />Get File Exists [ "$file" ; Target: $fileExists ]<br />If [ not $fileExists ]<br />&#160;&#160;&#160;&#160;Exit Script [ Text Result: ]<br />End If<br />Open Data File [ "$file" ; Target: $fileID ]<br />Read from Data File [ File ID: $fileID ; Amount (bytes): 100 ; Target: Utilities::Log Entry ; Read as: UTF-8 ]<br />Close Data File [ File ID: $fileID ]</code></pre>
                                            </div>
                                        </div>
                                        <h2 class="ref-examplen-head" data-mc-autonum="Example 3"><span class="autonumber"><span>Example 3</span></span>&#160;</h2>
                                        <p>If the large.log file exists and is large, reads the file 64 MB at a time into a variable until the entire file is read. If the file is smaller, it reads the entire file in one read operation. Data is read into a variable for improved performance, then the data is stored in a field.</p>
                                        <div class="codeSnippet"><a class="codeSnippetCopyButton" role="button" href="javascript:void(0);">Copy</a>
                                            <div class="codeSnippetBody" data-mc-use-line-numbers="False" data-mc-line-number-start="1" data-mc-continue="False"><pre><code>Set Error Capture [ On ]<br />Set Variable [ $k_FileMissingError ; Value: 100 ]&#160;<br />Set Variable [ $k_EndOfFileError ; Value: 10 ]<br />Set Variable [ $k_64KB ; Value: 64 * 1024 ]<br />Set Variable [ $k_64MB ; Value: 64 * 1024 * 1024 ]<br />Set Variable [ $file ; Value: "large.log" ]<br />Get File Exists [ "$file" ; Target : $fileExists ]<br />If [ $fileExists = 0 ]<br />&#160;&#160;&#160;&#160;Exit Script [ Result: $k_FileMissingError ]<br />End If<br /><br />Open Data File [ "$file" ; Target: $fileID ]&#160;<br /><br />#If the file opened successfully, read the contents.<br />If [ Get ( LastError ) = 0 ]<br />&#160;&#160;&#160;&#160;Get File Size [ "$file" ; Target: $fileSize ]<br /><br />&#160;&#160;&#160;&#160;#If the file size is greater than 64 KB, read it 64 MB at a time.<br />&#160;&#160;&#160;&#160;If [ $fileSize &gt; $k_64KB ]<br /><br />&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Loop [ Flush: Always ]<br />&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;#Read up to 64 MB and store it in a variable.<br />&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Read from Data File [ File ID: $fileID ; Amount (bytes): $k_64MB ; Target: $dataChunk ; Read as: UTF-8 ]<br />&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Set Variable [ $readError; Value:Get ( LastError ) ]<br /><br />&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;#If the read operation was successful or if the end of the file was reached, concatenate the data read in this pass ($dataChunk) with the data read previously ($fileContents).<br />&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;If [ ( $readError = 0 ) or ( $readError = $k_EndOfFileError ) ]<br />&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Set Variable [ $fileContents ; Value: $fileContents &amp; $dataChunk ]<br />&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;End If<br /><br />&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;#Exit the loop if the read operation failed or the end of the file is reached.<br />&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Exit Loop If [ $readError ]<br />&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;End Loop<br /><br />&#160;&#160;&#160;&#160;Else<br />&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;#If the file is no larger than 64 KB, read it all at once.<br />&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Read from Data File [ File ID: $fileID ; Target: $fileContents ; Read as: UTF-8 ]<br />&#160;&#160;&#160;&#160;End If<br /><br />&#160;&#160;&#160;&#160;#Close the data file and store the contents in a field.<br />&#160;&#160;&#160;&#160;Close Data File [ File ID: $fileID ]<br />&#160;&#160;&#160;&#160;Set Field [ Table::Data ; $fileContents ]<br /><br />End If</code></pre>
                                            </div>
                                        </div>
